/**
 * 터미널 창의 전체 제목에서 사람이 매긴 태스크(세션) 이름만 꺼낸다.
 * Claude Code 는 스피너 글리프 뒤에 주제가 오고, pi 는 `앱 - 세션 - 폴더` 꼴이다.
 */

const SPINNER = /^[\p{So}\p{Sk}\s]+/u;

function stripSpinner(title: string): string {
	return title.replace(SPINNER, "").trim();
}

function claudeTitle(title: string): string | null {
	const topic = stripSpinner(title);
	if (!topic || topic === "Claude Code") return null;
	return topic;
}

function piTitle(title: string): string | null {
	const parts = stripSpinner(title)
		.split(" - ")
		.map((part) => part.trim());
	if (parts.length < 3) return null;
	const session = parts.slice(1, -1).join(" - ").trim();
	return session || null;
}

export function taskTitle(kind: string, title: string): string | null {
	if (!title?.trim()) return null;
	if (kind === "claude") return claudeTitle(title.trim());
	if (kind === "pi") return piTitle(title.trim());
	return null;
}
